const About: React.FC = () => {
  const [email, setEmail] = useState('');
  const [status, setStatus] = useState<'idle' | 'loading' | 'success' | 'error'>('idle');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email) return;

    setStatus('loading');

    try {
      // Replace with your Google Apps Script Web App URL
      const GOOGLE_SHEET_URL = 'https://script.google.com/macros/s/YOUR_SCRIPT_ID/exec';

      // Note: This requires CORS setup on the Apps Script side.
      // If the URL is not replaced, we simulate a successful submission for UI purposes.
      if (GOOGLE_SHEET_URL.includes('YOUR_SCRIPT_ID')) {
        await new Promise(resolve => setTimeout(resolve, 1000));
        setStatus('success');
        setEmail('');
        return;
      }

      await fetch(GOOGLE_SHEET_URL, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, timestamp: new Date().toISOString() }),
      });

      setStatus('success');
      setEmail('');
    } catch (err) {
      console.error(err);
      setStatus('error');
    }
  };

  return (
    <section id="about" className="py-24 bg-blush-100/20 px-6 scroll-mt-20">
      <div className="max-w-6xl mx-auto">
