            <div className="absolute -top-6 -right-6 w-32 h-32 bg-blush-300/20 rounded-full blur-3xl -z-10"></div>
          </div>

          <div className="space-y-8">
            <div>
              <h2 className="text-3xl md:text-5xl font-serif text-gray-900 leading-tight mb-4">
                A Calm Voice in a <br /> 
                <span className="text-blush-400 italic">Loud World</span>
              </h2>
              <div className="w-20 h-1.5 bg-blush-300 rounded-full"></div>
            </div>

            <div className="space-y-6 text-lg text-gray-600 leading-relaxed">
