        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: new URLSearchParams({ 
          ...formData,
          type: 'booking'
        }).toString(),
      });

      // Auto-trigger redirection
      setStatus('success');
      window.location.href = waLink;
    } catch (err) {
      // Fallback: Still redirect if lead capture fails
      window.location.href = waLink;
      setStatus('success');
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-gray-900/60 backdrop-blur-sm" onClick={onClose}></div>
      <div className="relative bg-white w-full max-w-lg rounded-[2.5rem] shadow-2xl overflow-hidden animate-fade-in">
        <button onClick={onClose} className="absolute top-6 right-6 p-2 text-gray-400 hover:text-gray-900"><X size={24} /></button>

        {status === 'loading' ? (
          <div className="p-20 text-center flex flex-col items-center gap-6">
             <Loader2 size={48} className="text-blush-400 animate-spin" />
             <p className="text-lg font-bold text-gray-700">Saving details & opening WhatsApp...</p>
          </div>
        ) : status === 'success' ? (
          <div className="p-20 text-center flex flex-col items-center gap-6">
             <div className="w-16 h-16 bg-green-100 text-green-600 rounded-full flex items-center justify-center"><Check size={32} /></div>
             <p className="text-lg font-bold text-gray-700">Redirecting to WhatsApp!</p>
          </div>
        ) : (
          <div className="p-8 md:p-12">
            <h2 className="text-3xl font-bold text-gray-900 mb-2">Book a Call</h2>
            <p className="text-gray-500 mb-8 font-medium">Please enter your details. We will automatically take you to WhatsApp to confirm your slot.</p>
            <form onSubmit={handleBookingSubmit} className="space-y-5">
              <div>
                <label className="block text-sm font-bold text-gray-700 mb-2 uppercase tracking-widest text-[10px]">Full Name</label>
                <input required name="name" value={formData.name} onChange={handleInputChange} type="text" placeholder="Your Name" className="w-full bg-gray-50 border border-gray-100 rounded-2xl py-4 px-5 focus:ring-2 focus:ring-blush-400 outline-none" />
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-bold text-gray-700 mb-2 uppercase tracking-widest text-[10px]">Phone Number</label>
                  <input required name="phone" value={formData.phone} onChange={handleInputChange} type="tel" placeholder="+91..." className="w-full bg-gray-50 border border-gray-100 rounded-2xl py-4 px-5 focus:ring-2 focus:ring-blush-400 outline-none" />
                </div>
                <div>
                  <label className="block text-sm font-bold text-gray-700 mb-2 uppercase tracking-widest text-[10px]">Service</label>
                  <select name="service" value={formData.service} onChange={handleInputChange} className="w-full bg-gray-50 border border-gray-100 rounded-2xl py-4 px-5 focus:ring-2 focus:ring-blush-400 outline-none appearance-none">
                    {services.map(s => <option key={s} value={s}>{s}</option>)}
                  </select>
                </div>
              </div>
              <div>
                <label className="block text-sm font-bold text-gray-700 mb-2 uppercase tracking-widest text-[10px]">Email Address</label>
                <input required name="email" value={formData.email} onChange={handleInputChange} type="email" placeholder="email@example.com" className="w-full bg-gray-50 border border-gray-100 rounded-2xl py-4 px-5 focus:ring-2 focus:ring-blush-400 outline-none" />
              </div>
              <button type="submit" className="w-full bg-blush-400 text-white py-5 rounded-2xl font-bold text-lg flex items-center justify-center gap-3 hover:bg-blush-500 shadow-lg active:scale-95 transition-all">
                Submit & Open WhatsApp <Send size={20} />
              </button>
            </form>
          </div>
        )}
      </div>
    </div>
  );
};

